import QRCode from "qrcode";

import { cn } from "@/lib/utils";

/** A QR code for `value`, drawn on the server as inline SVG. */
export async function QrCode({ value, label, className }: { value: string; label: string; className?: string }) {
  const svg = await QRCode.toString(value, { type: "svg", margin: 0, errorCorrectionLevel: "M", color: { dark: "#111111", light: "#ffffff" } });
  return (
    <div
      role="img"
      aria-label={label}
      className={cn("aspect-square [&>svg]:size-full", className)}
      // Generated by the qrcode library from our own URL; contains no user input.
      dangerouslySetInnerHTML={{ __html: svg }}
    />
  );
}
